SELECT *
FROM t_hospital
WHERE id = #{hospitalId}
  AND state = 'ACTIVE'
  AND deleted_yn = 'N';

SELECT file.path
FROM t_hospital hos
	     JOIN t_files file ON hos.image_group_id = file.group_id
WHERE hos.image_group_id = #{groupId}
  AND file.file_order = 1;

SELECT event.id AS id, event.image_group_id AS imageGroupId, hos.city AS city, hos.district AS district, event.name AS name, event.consult_count AS counselCount, event.price AS cost FROM t_event event JOIN t_hospital hos ON hos.id = event.hospital_id WHERE hos.id = #{hospitalId} AND event.state='ACTIVE' AND event.type='EVENT'
AND event.category IN (
#{item}
)
ORDER BY CASE WHEN #{sort} = 'date_created' THEN event.date_created END DESC, CASE WHEN #{sort} = 'consult_count' THEN event.consult_count END DESC, CASE WHEN #{sort} = 'price' THEN event.price END DESC, CASE WHEN #{sort} = 'low_price' THEN event.price END LIMIT #{size} OFFSET #{page} * 10;

mapper.update:
UPDATE t_hospital
SET consult_count = #{consultCount}
WHERE id = #{id};

