SELECT COUNT(*)
FROM (
SELECT * FROM t_hospital
WHERE state = 'ACTIVE'
AND deleted_yn = 'N'

	AND name ILIKE '%' || #{keyword} || '%'


	AND ARRAY[medical_category] &&
	ARRAY[
	#{category, typeHandler=com.wannabe.app.main.utility.mybatis.StringListHandler}
	]::varchar[]


	AND city = #{city}


	AND district IN (

		#{item}

	)

ORDER BY

	${sort},

exposed_rank
) AS subquery

SELECT * FROM t_article a WHERE a.review_type_id IN (SELECT e.id FROM t_event e WHERE e.hospital_id = #{hospitalId} AND e.state = 'ACTIVE' AND e.type = 'EVENT' ORDER BY e.date_created)
AND (
array_to_string(a.category, ',') LIKE '%' || #{item} || '%'
)
AND a.available_yn='Y' AND a.review_type = 'EVENT' ORDER BY CASE WHEN #{sort} = 'date_created' THEN a.date_created END DESC, CASE WHEN #{sort} = 'view_count' THEN a.view_count END DESC LIMIT #{size} OFFSET #{page} * 10;
